pub assume_specification<'a, T>[ Option::<T>::iter ](
    option: &'a Option<T>,
) -> (iter: core::option::Iter<'a, T>)
    ensures
        IteratorSpec::obeys_prophetic_iter_laws(&iter),
        IteratorSpec::remaining(&iter) == (match option {
            Option::Some(value) => seq![value],
            Option::None => seq![],
        }),
        IteratorSpec::decrease(&iter) is Some,
        IteratorSpec::initial_value_relation(&iter, &iter),
;

pub assume_specification<'a, T, E>[ Result::<T, E>::iter ](
    result: &'a Result<T, E>,
) -> (iter: core::result::Iter<'a, T>)
    ensures
        IteratorSpec::obeys_prophetic_iter_laws(&iter),
        IteratorSpec::remaining(&iter) == (match result {
            Result::Ok(value) => seq![value],
            Result::Err(_) => seq![],
        }),
        IteratorSpec::decrease(&iter) is Some,
        IteratorSpec::initial_value_relation(&iter, &iter),
;
